// ⚙️ CONFIGURACIÓN — edita solo este bloque
const CONFIG = {
  // El token de GHL ya NO va aquí: vive en la credencial "GHL Private Integration" (ver SETUP.md)
  // GHL → Settings → Business Profile → Location ID
  locationId: 'PEGA_AQUI_TU_LOCATION_ID',
  // Nombre EXACTO del pipeline en GHL para cada marca (Opportunities → Pipelines)
  pipelines: { aipilot: 'AIPilot', capta: 'Capta', odyssai: 'ODYSSAI' },
  // Etapa de la app → nombre de la etapa en tu pipeline de GHL (si se llaman distinto)
  stageMap: {
    'Nuevo Lead': 'Nuevo Lead', 'Diagnóstico': 'Diagnóstico', 'Propuesta': 'Propuesta',
    'Negociación': 'Negociación', 'Cerrado': 'Cerrado', 'Perdido': 'Perdido',
  },
};

const body = $input.first().json.body || {};
const isProposal = body.type === 'proposal';
const lead = body.lead || {};
const p = isProposal ? (body.prospect || {}) : lead;
const brand = body.brand || lead.brand || '';
const brandName = body.brandName || brand;

const fullName = String(p.name || '').trim() || 'Sin nombre';
const [firstName, ...rest] = fullName.split(/\s+/);
let phone = String(p.phone || '').replace(/[^\d+]/g, '');
if (/^\d{10}$/.test(phone)) phone = '+52' + phone;           // número MX sin lada
else if (/^\d{11,15}$/.test(phone)) phone = '+' + phone;
const SOURCES = { 'meta-ads': 'Meta Ads', referido: 'Referido', organico: 'Orgánico', whatsapp: 'WhatsApp', 'sitio-web': 'Sitio web' };
const source = SOURCES[isProposal ? body.source : lead.source] || '';
const stage = isProposal ? 'Propuesta' : (lead.stage || 'Nuevo Lead');

const contact = {
  locationId: CONFIG.locationId,
  firstName,
  lastName: rest.join(' '),
  name: fullName,
  companyName: p.company || '',
  source: 'ODYSSAI CRM' + (source ? ' · ' + source : ''),
  tags: [brandName, isProposal ? 'propuesta-enviada' : 'crm'].filter(Boolean),
};
if (p.email) contact.email = String(p.email).trim().toLowerCase();
if (phone) contact.phone = phone;

const error = !CONFIG.locationId || CONFIG.locationId.startsWith('PEGA_AQUI')
  ? 'Falta el Location ID de GHL en el nodo "Preparar datos" de n8n'
  : (!contact.email && !contact.phone) ? 'El prospecto necesita email o WhatsApp para crearlo en GHL' : '';

return [{
  json: {
    error,
    locationId: CONFIG.locationId,
    contact,
    brand,
    pipelineName: CONFIG.pipelines[brand] || brandName,
    stage,
    ghlStageName: CONFIG.stageMap[stage] || stage,
    status: stage === 'Cerrado' ? 'won' : stage === 'Perdido' ? 'lost' : 'open',
    opportunityName: `${p.company || fullName} — ${brandName}`,
    amount: Number(isProposal ? body.amount : lead.amount) || 0,
  },
}];

// Traduce la respuesta de GHL a un mensaje claro para la app
const ghlError = (r, que) => {
  const s = r.statusCode;
  if (s >= 200 && s < 300) return '';
  const m = r.body?.message ?? r.error?.message ?? '';
  const det = Array.isArray(m) ? m.join(', ') : String(m || '');
  if (s === 401 || s === 403) return `GHL rechazó el token al ${que} (${s}). Revisa la credencial "GHL Private Integration" en n8n y sus permisos`;
  return `GHL respondió ${s || 'sin conexión'} al ${que}${det ? ': ' + det : ''}`;
};

// Busca el pipeline y la etapa de GHL por nombre (sin importar acentos ni mayúsculas)
const d = $('Preparar datos').first().json;
const c = $('GHL: crear/actualizar contacto').first().json;
const p = $input.first().json;
const error = ghlError(c, 'crear el contacto') || ghlError(p, 'leer los pipelines');
const contactId = c.body?.contact?.id || '';
const pipelines = p.body?.pipelines || [];
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();
const pipe = pipelines.find(x => norm(x.name) === norm(d.pipelineName));
const stage = pipe && ((pipe.stages || []).find(s => norm(s.name) === norm(d.ghlStageName)) || (pipe.stages || [])[0]);
return [{
  json: {
    ...d,
    error: error || (!contactId ? 'GHL no devolvió el contacto' : ''),
    contactId,
    pipelineId: pipe ? pipe.id : '',
    pipelineStageId: stage ? stage.id : '',
    aviso: (error || pipe) ? '' : `No existe un pipeline llamado "${d.pipelineName}" en GHL; solo se creó el contacto`,
  },
}];

// Traduce la respuesta de GHL a un mensaje claro para la app
const ghlError = (r, que) => {
  const s = r.statusCode;
  if (s >= 200 && s < 300) return '';
  const m = r.body?.message ?? r.error?.message ?? '';
  const det = Array.isArray(m) ? m.join(', ') : String(m || '');
  if (s === 401 || s === 403) return `GHL rechazó el token al ${que} (${s}). Revisa la credencial "GHL Private Integration" en n8n y sus permisos`;
  return `GHL respondió ${s || 'sin conexión'} al ${que}${det ? ': ' + det : ''}`;
};

const d = $('Ubicar pipeline y etapa').first().json;
const r = $input.first().json;
return [{ json: { ...d, error: ghlError(r, 'crear la oportunidad'), opportunityId: r.body?.opportunity?.id || '' } }];
